/* Shared local proxy workbench; all probes and credentials are fictitious. */
'use strict';
let proxyEditor=null,proxyJob=null,proxyDeleteDraft=null,proxyImportRows=[],proxyExportIds=[];
const defaultProxyFilters=()=>({q:'',protocol:'all',state:'all',region:'all',usage:'all',start:'',end:'',sort:'created',direction:'desc'});
let proxyFilters=defaultProxyFilters(),proxySelected=new Set(),proxyPage=1,proxySize=10,proxyContext='',proxyRefresh='演示快照 · 10/15 14:20';
const PROXY_COUNTRIES=[['US','美国'],['TW','中国台湾'],['JP','日本'],['SG','新加坡'],['DE','德国'],['CA','加拿大'],['','未配置']];
const regionLabel=code=>PROXY_COUNTRIES.find(x=>x[0]===code)?.[1]||'未配置';
function validProxyDate(value){return value==null||value===''||typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&Number.isFinite(Date.parse(value))&&new Date(value).toISOString().slice(0,10)===value;}
function proxyExpired(p){return !!p.expires&&p.expires<DEMO_TODAY;}
function proxyStatus(p){return p.enabled===false?'已停用':proxyExpired(p)?'已过期':p.state==='异常'?'异常':p.state==='可用'?'可用':'未测试';}
function proxyOperational(p){return p.enabled!==false&&!proxyExpired(p);}
function proxyOwner(p){return vendors.find(v=>v.id===(p.vendorId||1));}
function proxyBindings(id){return allAccounts().filter(a=>a.proxy===id);}
function canReadProxy(p){return window.vendorHierarchy?VendorHierarchyModel.resourceAccess(window.vendorHierarchy.actor,p,vendors).read:canManageProxy(p);}
function proxyReferences(p){const bindings=proxyBindings(p.id),backup=allProxies().filter(x=>x.backup===p.id),sessions=p.pendingSessions||0;return {bindings,backup,sessions,blocked:bindings.length+backup.length+sessions>0};}
function selectableProxies(vendorId,current){return allProxies().filter(p=>(p.vendorId||1)===vendorId&&(proxyOperational(p)||p.id===current));}
function canManageProxy(p){if(window.vendorHierarchy)return VendorHierarchyModel.resourceAccess(window.vendorHierarchy.actor,p,vendors).manage;return !!p&&(previewRole==='super_admin'&&!portalMode||previewRole==='vendor'&&(p.vendorId||1)===ownerPolicy().id&&ownerPolicy().status==='active');}
function nextProxyId(){return Math.max(0,...allProxies().map(p=>p.id))+1;}
function stampProxy(p){p.country??='';p.city??='';p.enabled??=true;p.hasAuth??=false;p.created??=DEMO_TODAY+'T14:20:00+08:00';p.expires??='';p.version??=1;p.notes??='';p.createdBy??='供应商本人';return p;}
function seedProxyMetadata(){
 const samples=[['US','洛杉矶',118],['TW','台北',236],['SG','新加坡',null],['','',null],['JP','东京',162],['US','纽约',null],['DE','法兰克福',280],['CA','多伦多',null],['TW','高雄',1170],['SG','新加坡',93],['JP','大阪',208],['','',null]];
 for(let i=4;i<=12;i++)if(!proxies.some(p=>p.id===i))proxies.push({id:i,name:['故障出口 D','日本备用 E','到期出口 F','停用出口 G','待授权出口 H','高延迟出口 I','新加坡出口 J','大阪出口 K','备用链出口 L'][i-4],host:'proxy-'+String.fromCharCode(96+i)+'.example.invalid',port:i%2?1080:8080,protocol:['HTTP','HTTPS','SOCKS5','SOCKS5H'][i%3],state:i===4?'异常':[8,12].includes(i)?'未测试':'可用'});
 proxies.forEach((p,i)=>{stampProxy(p);const x=samples[i];if(!x)return;Object.assign(p,{country:x[0],city:x[1],latency:x[2],geoSource:i===2?'手动标签':'演示检测',hasAuth:[0,1,3,8].includes(i),created:'2026-10-'+String(15-i).padStart(2,'0')+'T10:20:00+08:00',expires:i===5?'2026-10-12':i===4?'2026-10-20':'',enabled:i!==6,lastTest:x[2]===null?'':DEMO_NOW});if(i===3)p.simFailure=true;if(i===7)p.pendingSessions=1;if(i===11)p.backup=3;if(x[2]!==null)p.quality={grade:i===8?'C':'A',score:i===8?67:94-i,summary:i===8?'部分目标受限':'目标可达',latency:x[2],at:DEMO_NOW};});
 const a=accounts.find(a=>a.id===112);if(a)a.proxy=4;
 extraProxies.forEach((p,i)=>Object.assign(stampProxy(p),{country:PROXY_COUNTRIES[i%6][0],city:'演示地区',latency:150+i*21,geoSource:'演示检测',hasAuth:i%2===0,created:'2026-10-01T09:00:00+08:00',lastTest:DEMO_NOW,createdBy:i%2===0?'超级管理员':'供应商本人'}));
}
function resetProxyWorkspace(){proxyJob&&(proxyJob.cancelled=true);proxyJob=null;proxyEditor=null;proxyDeleteDraft=null;proxyFilters=defaultProxyFilters();proxySelected.clear();proxyPage=1;proxySize=10;proxyRefresh='演示快照 · 10/15 14:20';proxyContext='';seedProxyMetadata();}
function proxyScope(admin=previewRole==='super_admin'){return allProxies().filter(p=>admin?(adminFilters.vendor==='all'||(p.vendorId||1)===Number(adminFilters.vendor)):(p.vendorId||1)===ownerPolicy().id).map(stampProxy);}
function ensureProxyContext(admin){const key=admin?'admin:'+adminFilters.vendor:'vendor:'+ownerPolicy().id;if(proxyContext!==key){proxyContext=key;proxySelected.clear();proxyFilters=defaultProxyFilters();proxyPage=1;}return proxyScope(admin);}
function filteredProxies(){const f=proxyFilters;const rows=proxyScope().filter(p=>(!f.q||(p.id+' '+p.name+' '+p.host).toLowerCase().includes(f.q.toLowerCase()))&&(f.protocol==='all'||p.protocol===f.protocol)&&(f.state==='all'||proxyStatus(p)===f.state)&&(f.region==='all'||(p.country||'unknown')===f.region)&&(f.usage==='all'||(proxyBindings(p.id).length>0)===(f.usage==='used'))&&(!f.start||p.created.slice(0,10)>=f.start)&&(!f.end||p.created.slice(0,10)<=f.end));
 const value=p=>f.sort==='accounts'?proxyBindings(p.id).length:f.sort==='latency'?p.latency??Infinity:f.sort==='expires'?p.expires||'9999':p[f.sort];
 return rows.sort((a,b)=>{if(f.sort==='latency'){if(a.latency==null&&b.latency!=null)return 1;if(b.latency==null&&a.latency!=null)return -1;}const av=value(a),bv=value(b),n=typeof av==='number'?av-bv:String(av).localeCompare(String(bv),'zh-CN');return (f.direction==='asc'?n:-n)||a.id-b.id;});
}
function proxySummaryHtml(rows){const used=rows.filter(p=>proxyBindings(p.id).length),invalid=used.filter(p=>['异常','已停用','已过期'].includes(proxyStatus(p)));return `<div class="proxy-summary" aria-label="代理概览">${[['总代理数',rows.length],['已占用',used.length],['占用中异常 / 不可用',invalid.length],['未占用',rows.length-used.length]].map(([k,v],i)=>`<div class="${i===2?'negative':''}"><span>${k}</span><strong>${v}</strong></div>`).join('')}<small>${proxyRefresh} · 不随筛选变化</small></div>`;}
function proxyFilter(key,label,items){return `<label>${label}<select data-px-filter="${key}" aria-label="${label}">${options(items,proxyFilters[key])}</select></label>`;}
function proxyWorkspace(admin=false){const rows=ensureProxyContext(admin);return `${admin?proxySummaryHtml(rows):''}<section class="panel proxy-workbench"><div class="proxy-toolbar"><input id="proxy-search" aria-label="搜索代理" placeholder="输入代理地址或 IP" value="${esc(proxyFilters.q)}"><div class="proxy-filters">${admin?adminSelect('vendor','供应商',[['all','全部供应商'],...vendors.map(v=>[v.id,v.name])]):''}${proxyFilter('protocol','协议',[['all','全部协议'],...['HTTP','HTTPS','SOCKS5','SOCKS5H'].map(v=>[v,v])])}${proxyFilter('state','状态',[['all','全部状态'],...['可用','异常','未测试','已停用','已过期'].map(v=>[v,v])])}${proxyFilter('region','国家 / 地区',[['all','全部地区'],...PROXY_COUNTRIES.map(([id,label])=>[id||'unknown',label])])}${proxyFilter('usage','使用状态',[['all','全部'],['used','已占用'],['free','未占用']])}<details class="proxy-extra-filters"><summary>更多筛选</summary><div><label>导入 / 创建时间（起）<input type="date" id="proxy-start" value="${proxyFilters.start}" max="${DEMO_TODAY}"></label><label>至<input type="date" id="proxy-end" value="${proxyFilters.end}" max="${DEMO_TODAY}"></label><button data-action="px-dates">应用日期</button><button data-action="px-sort" data-sort="protocol">按协议排序</button><button data-action="px-sort" data-sort="expires">按有效期排序</button></div></details><button class="quiet" data-action="px-reset">重置</button></div><div class="proxy-tools"><button data-action="px-refresh" title="仅刷新列表，不触发检测" aria-label="刷新代理">${workbenchIcon("refresh")}</button><button class="proxy-test-all" data-action="px-test" data-kind="connect">${workbenchIcon("checkCircle")}<span>一键测试</span></button><button data-action="px-test" data-kind="quality">${workbenchIcon("shield")}<span>质量检测</span></button><button data-action="px-delete" class="danger" data-px-selected disabled>删除已选</button><button data-action="px-import">导入</button><button data-action="px-export">导出</button><button class="primary" data-action="px-add">${workbenchIcon("plus")}<span>新增代理</span></button></div></div><p id="proxy-filter-error" class="form-error" role="alert"></p><div class="proxy-selection" id="proxy-selection"></div><div id="proxy-test-status" class="proxy-test-status" role="status" aria-live="polite"></div><div class="table-wrap"><table class="proxy-table proxy-rich" aria-label="${admin?'供应商代理工作台':'我的代理工作台'}"><thead><tr><th><input type="checkbox" id="proxy-select-page" aria-label="选择当前页代理"></th>${[['','ID'],['name','代理地址'],['','国家 / 地区'],['','创建者'],['','共享范围'],['accounts','占用'],['','占用账号'],['created','导入 / 创建时间'],['latency','状态'],['','操作']].map(([key,label])=>`<th>${key?`<button class="sort-button" data-action="px-sort" data-sort="${key}">${prototypeText(label)} ${proxyFilters.sort===key?(proxyFilters.direction==='asc'?'↑':'↓'):'↕'}</button>`:label}</th>`).join('')}</tr></thead><tbody id="proxy-rows">${proxyRowHtml()}</tbody></table></div><div id="proxy-pager">${proxyPagerHtml()}</div></section><div class="notice">占用数为绑定账号数，不是并发或限额。专属代理只在同一供应商内使用；认证、有效期、质量和引用在详情中查看。修改出口保留账号授权。</div>`;}

function renderProxies(){const rows=ensureProxyContext(false);$('view').innerHTML=heading('代理管理','管理我的专属出口、占用情况与可用状态',proxySummaryHtml(rows))+proxyWorkspace(false);renderProxyData();}
function proxyRowHtml(){
 const rows=filteredProxies(),max=Math.max(1,Math.ceil(rows.length/proxySize));proxyPage=Math.min(proxyPage,max);
 return rows.slice((proxyPage-1)*proxySize,proxyPage*proxySize).map(p=>{
  const bindings=proxyBindings(p.id),state=proxyStatus(p),testing=proxyJob?.running&&proxyJob.rows.some(r=>r.id===p.id&&r.state==='检测中');
  const busy=!!proxyJob?.running,qualityAction=p.quality?'px-report':'px-test',qualityTitle=p.quality?'查看质量报告':'质量检测';
  const testTitle=testing?'测试中':proxyOperational(p)?'测试连接':'停用或过期的代理不执行测试';
  return `<tr class="${proxySelected.has(p.id)?'selected':''}"><td><input type="checkbox" data-px-select="${p.id}" aria-label="${prototypeText('选择代理 {id}',{id:p.id})}" ${proxySelected.has(p.id)?'checked':''}></td><td>${p.id}</td><td><div class="proxy-address"><button class="text-button" data-action="proxy-detail" data-id="${p.id}" title="${esc(p.name)}">${esc(p.name)}</button><div><span class="badge info">${p.protocol}</span><code>${esc(p.host)}:${p.port}</code><button class="icon-button" data-action="px-copy" data-id="${p.id}" title="${prototypeText('复制代理地址（不含认证）')}" aria-label="${prototypeText('复制代理 {id} 地址',{id:p.id})}">${workbenchIcon('copy')}</button></div></div></td><td title="${esc(p.geoSource||'未检测')}">${prototypeText(regionLabel(p.country))}${p.city?' · '+esc(prototypeText(p.city)):''}</td><td>${esc(p.createdBy)}</td><td>供应商专属</td><td><button class="text-button" data-action="proxy-detail" data-id="${p.id}">${bindings.length}</button></td><td>${bindings.length?`<button class="text-button" data-action="proxy-detail" data-id="${p.id}">#${bindings.slice(0,2).map(a=>a.id).join('、#')}${bindings.length>2?' …':''}</button>`:'<span class="muted">未占用</span>'}</td><td>${p.created.replace('T',' ').slice(0,16)}</td><td><div class="proxy-status">${testing?workbenchIcon('refresh',true):''}<span class="badge ${state==='可用'?'ok':['异常','已过期'].includes(state)?'error':'info'}">${testing?'测试中':state}</span>${p.latency==null||testing?'':`<span class="${p.latency>800?'amber':'green'}">${p.latency} ms</span>`}</div></td><td><div class="proxy-row-actions"><button data-action="px-test" data-id="${p.id}" data-kind="connect" title="${prototypeText(testTitle)}" aria-label="${prototypeText(testTitle)} · #${p.id}" ${busy||!proxyOperational(p)?'disabled':''} aria-busy="${testing}">${workbenchIcon(testing?'refresh':'checkCircle',testing)}</button><button data-action="${qualityAction}" data-id="${p.id}" data-kind="quality" title="${prototypeText(qualityTitle)}" aria-label="${prototypeText(qualityTitle)} · #${p.id}" ${busy?'disabled':''}>${workbenchIcon('shield')}</button><button data-action="edit-proxy" data-id="${p.id}" title="${prototypeText('编辑')}" aria-label="${prototypeText('编辑')} · #${p.id}">${workbenchIcon('edit')}</button><button data-action="px-delete" data-id="${p.id}" class="danger" title="${prototypeText('删除')}" aria-label="${prototypeText('删除')} · #${p.id}" ${busy?'disabled':''}>${workbenchIcon('trash')}</button></div></td></tr>`;
 }).join('')||'<tr><td colspan="11" class="empty">没有符合条件的代理。调整筛选或添加自己的代理。</td></tr>';
}

function proxyPagerHtml(){const n=filteredProxies().length,max=Math.max(1,Math.ceil(n/proxySize));return `<div class="pagination"><span>${prototypeText('共 {count} 条 · 每页',{count:n})} <select id="proxy-page-size" aria-label="代理每页条数">${options([10,20,50].map(n=>[n,n]),proxySize)}</select> 条</span><div class="row"><button data-action="px-page" data-page="1" ${proxyPage===1?'disabled':''}>«</button><button data-action="px-page" data-page="${proxyPage-1}" ${proxyPage===1?'disabled':''}>上一页</button><span>${proxyPage} / ${max}</span><button data-action="px-page" data-page="${proxyPage+1}" ${proxyPage===max?'disabled':''}>下一页</button><button data-action="px-page" data-page="${max}" ${proxyPage===max?'disabled':''}>»</button></div></div>`;}
function renderProxyData(){if(!$('proxy-rows'))return;$('proxy-rows').innerHTML=proxyRowHtml();$('proxy-pager').innerHTML=proxyPagerHtml();updateProxySelection();renderProxyJob();}
function updateProxySelection(){const scoped=new Set(filteredProxies().map(p=>p.id));proxySelected=new Set([...proxySelected].filter(id=>scoped.has(id)));const nodes=[...document.querySelectorAll('[data-px-select]')],checked=nodes.filter(n=>proxySelected.has(Number(n.dataset.pxSelect))).length;const select=$('proxy-select-page');if(select){select.checked=nodes.length>0&&checked===nodes.length;select.indeterminate=checked>0&&checked<nodes.length;select.disabled=!nodes.length;}$('proxy-selection').hidden=!proxySelected.size;$('proxy-selection').innerHTML=`<span>${prototypeText('已选 {count} 个（可跨页） · 当前筛选 {filtered} 个',{count:proxySelected.size,filtered:filteredProxies().length})}</span><span>未勾选时，测试与导出作用于当前筛选的全部结果</span><button class="text-button" data-action="px-clear">清空选择</button>`;document.querySelectorAll('[data-px-selected]').forEach(b=>b.disabled=!proxySelected.size||!!proxyJob?.running);renderProxyJob();}
function refreshProxyWorkspace(){if(previewRole==='super_admin')renderAdmin();else if(page==='proxies')renderProxies();if($('proxy-rows'))renderProxyData();}
function proxyTargets(id){return id?allProxies().filter(p=>p.id===id&&canManageProxy(p)):proxySelected.size?proxyScope().filter(p=>proxySelected.has(p.id)):filteredProxies();}
function proxyFields(prefix,p=null){return `<div class="fieldgrid"><label>代理名称<input id="${prefix}-name" maxlength="100" value="${esc(p?.name||'')}" placeholder="例如：专属出口 D"></label><label>协议<select id="${prefix}-protocol">${options(['HTTP','HTTPS','SOCKS5','SOCKS5H'].map(x=>[x,x]),p?.protocol||'HTTP')}</select></label><label>主机<input id="${prefix}-host" value="${esc(p?.host||'demo.example.invalid')}" autocomplete="off"></label><label>端口<input id="${prefix}-port" type="number" min="1" max="65535" value="${p?.port||8080}"></label><label>国家 / 地区<select id="${prefix}-country">${options(PROXY_COUNTRIES,p?.country||'')}</select></label><label>城市 / 地区标签<input id="${prefix}-city" maxlength="100" value="${esc(p?.city||'')}"></label><label>有效期（留空为永不过期）<input id="${prefix}-expires" type="date" value="${p?.expires||''}"></label><label>认证设置<select id="${prefix}-auth-mode" data-px-auth="${prefix}">${options([['keep',p?.hasAuth?'保留现有认证':'不配置认证'],['set','更新认证（演示）'],['clear','清除代理认证']], 'keep')}</select></label><label>用户名（演示）<input id="${prefix}-username" autocomplete="off" placeholder="DEMO_USER" disabled></label><label>密码（演示）<input id="${prefix}-password" type="password" autocomplete="new-password" placeholder="DEMO_PASSWORD" disabled></label><label class="wide">备注<textarea id="${prefix}-notes" maxlength="300" rows="2">${esc(p?.notes||'')}</textarea></label></div><label class="checkline"><input id="${prefix}-enabled" type="checkbox" ${p?.enabled===false?'':'checked'}>启用此代理</label><p class="muted small">有效期截至所选日 23:59（UTC+8）。地区可手动标注，与检测结果区分。原型只接受 .invalid 域名和 DEMO_ 认证；认证字符串不保存、不导出。</p><p id="${prefix}-error" class="form-error" role="alert"></p>`;}
function proxyWidget(prefix,mode='standard'){const tabs=[['standard','＋ 标准添加'],['quick','≡ 快捷添加'],...(prefix==='inline'?[]:[['json','↑ 文件导入']])];return `<div class="proxy-tabs" role="tablist" aria-label="代理添加方式">${tabs.map(([key,label])=>`<button role="tab" aria-selected="${mode===key}" data-action="proxy-tab" data-prefix="${prefix}" data-tab="${key}">${label}</button>`).join('')}</div>${mode==='standard'?proxyFields(prefix):mode==='json'?proxyJsonFields():`<label>代理列表<textarea id="${prefix}-quick" data-quick="${prefix}" rows="7" spellcheck="false" placeholder="每行一个代理：&#10;socks5://DEMO_USER:DEMO_PASSWORD@proxy-m.example.invalid:1080&#10;http://proxy-n.example.invalid:8080&#10;https://proxy-o.example.invalid:443"></textarea></label><p class="muted small">HTTP / HTTPS / SOCKS5 / SOCKS5H · 必须带端口。仅 .invalid 演示域名；认证字符不保存。最多100行 / 32 KB。</p><div id="${prefix}-quick-preview"></div><p id="${prefix}-error" class="form-error" role="alert"></p><button class="primary" id="${prefix}-quick-submit" data-action="quick-proxies" data-prefix="${prefix}" disabled>导入 0 个代理</button>`}`;}
function editorOwner(prefix){return prefix==='inline'?1:proxyEditor?.vendor||Number($('proxy-owner')?.value)||0;}
function openProxyEditor(id=null,tab='standard'){const p=allProxies().find(p=>p.id===id);if(p&&!canManageProxy(p))return;proxyEditor={id,tab,vendor:p?(p.vendorId||1):previewRole==='super_admin'?(adminFilters.vendor==='all'?0:Number(adminFilters.vendor)):ownerPolicy().id};accountForm=null;renderProxyEditor();}
function renderProxyEditor(){const p=allProxies().find(p=>p.id===proxyEditor.id);const owner=previewRole==='super_admin'?`<label class="proxy-owner-field">供应商归属<select id="proxy-owner" ${p?'disabled':''}>${options([['0','请选择供应商'],...vendors.map(v=>[v.id,v.name])],proxyEditor.vendor)}</select></label>`:'';openModal(p?'编辑代理':'新增我的专属代理',p?'端点、认证和有效期修改均保留账号授权':'标准添加、快捷多行和文件导入 · 原型',owner+(p?`<div class="notice">影响 ${proxyBindings(p.id).length} 个账号。停用或到期会停止这些账号的新派发；不会删除凭证、修改账号暂停或历史。</div>${proxyFields('proxy',p)}`:proxyWidget('proxy',proxyEditor.tab)),`<button data-action="dismiss">取消</button>${p||proxyEditor.tab==='standard'?'<button class="primary" data-action="save-proxy">保存代理</button>':''}`);}
function parseProxyLines(text,prefix='proxy'){const lines=text.split(/\r?\n/).map((raw,i)=>({raw:raw.trim(),line:i+1})).filter(r=>r.raw),seen=new Set(),vendor=editorOwner(prefix);if(lines.length>100||text.length>32000)return [{line:0,error:'每次最多100行、32 KB'}];return lines.map(({raw,line})=>{try{if(!vendor)throw Error('请先选择供应商');const u=new URL(raw);if(!['http:','https:','socks5:','socks5h:'].includes(u.protocol)||!/^([a-z0-9-]+\.)+invalid$/i.test(u.hostname)||u.search||u.hash||(u.pathname&&u.pathname!=='/'))throw Error('需要 HTTP / HTTPS / SOCKS5 / SOCKS5H 的 .invalid 演示地址');const port=Number(raw.match(/:(\d+)(?:\/)?$/)?.[1]);if(!Number.isInteger(port)||port<1||port>65535)throw Error('必须明确填写 1–65535 端口');const username=decodeURIComponent(u.username),password=decodeURIComponent(u.password);if((username||password)&&(!username.startsWith('DEMO_')||!password.startsWith('DEMO_')))throw Error('原型认证仅接受成对 DEMO_ 用户名和密码');const protocol=u.protocol.slice(0,-1).toUpperCase(),key=protocol+'|'+u.hostname+'|'+port;if(seen.has(key)||allProxies().some(p=>(p.vendorId||1)===vendor&&p.protocol===protocol&&p.host===u.hostname&&p.port===port))throw Error('同一供应商已存在或输入重复');seen.add(key);return {line,host:u.hostname,port,protocol,hasAuth:!!(u.username||u.password)};}catch(e){return {line,error:e instanceof URIError?'认证编码错误':e instanceof TypeError?'地址格式无效':e.message};}});}
function previewQuick(prefix,rows=parseProxyLines($(prefix+'-quick').value,prefix)){const count=rows.filter(r=>!r.error&&!r.added).length;$(prefix+'-error').textContent='';$(prefix+'-quick-submit').disabled=!count;$(prefix+'-quick-submit').textContent='导入 '+count+' 个代理';$(prefix+'-quick-preview').innerHTML=rows.length?`<div class="quick-preview">${rows.map(r=>`<div><span>第 ${r.line} 行</span><span class="${r.error?'form-error':'muted'}">${esc(r.error||(r.added?'✓ 已添加 · ':'')+r.protocol+' · '+r.host+':'+r.port)}</span></div>`).join('')}</div>`:'';}
function appendProxy(data,vendor){const p=stampProxy({id:nextProxyId(),vendorId:vendor,createdBy:previewRole==='super_admin'?'超级管理员':'供应商本人',...data,state:'未测试',geoSource:data.country?'手动标签':'未检测'});(vendor===ownerPolicy().id?proxies:extraProxies).push(p);return p;}
function proxyAudit(p,action,result){adminEvents.unshift({at:'2026-10-15 14:20',vendor:p.vendorId||1,actor:previewRole==='super_admin'?'超级管理员':'供应商本人',action,result});}
function saveQuickProxies(prefix){const vendor=editorOwner(prefix),v=vendors.find(x=>x.id===vendor),rows=parseProxyLines($(prefix+'-quick').value,prefix),valid=rows.filter(r=>!r.error);if(!valid.length)return;if(!v||vendorProxies(v).length+valid.length>v.proxyLimit){$(prefix+'-error').textContent='超过该供应商代理上限';return;}let first;for(const r of valid){const p=appendProxy({name:'专属出口 '+nextProxyId(),host:r.host,port:r.port,protocol:r.protocol,hasAuth:r.hasAuth},vendor);first??=p.id;proxyAudit(p,'快捷导入代理','#'+p.id+' · 仅保存演示认证状态');}if(prefix==='inline'){accountForm.proxy=first;accountForm.inline=false;renderAccountForm();}else if(rows.some(r=>r.error)){refreshProxyWorkspace();previewQuick(prefix,rows.map(r=>r.error?r:{...r,added:true}));$('modal-actions').innerHTML='<button data-action="dismiss">完成</button>';$(prefix+'-error').textContent='已添加 '+valid.length+' 个，其余行未导入；关闭不撤销成功行。';}else{$('modal').close();refreshProxyWorkspace();}notify('已添加 '+valid.length+' 个演示代理，账号授权未改变。');}
function saveProxy(prefix,inline){const existing=inline?null:allProxies().find(p=>p.id===proxyEditor?.id),vendor=editorOwner(prefix),v=vendors.find(x=>x.id===vendor),name=$(prefix+'-name').value.trim(),host=$(prefix+'-host').value.trim().toLowerCase(),port=Number($(prefix+'-port').value),protocol=$(prefix+'-protocol').value,mode=$(prefix+'-auth-mode').value;
 if(!v||existing&&!canManageProxy(existing)||!name||!/^([a-z0-9-]+\.)+invalid$/i.test(host)||!Number.isInteger(port)||port<1||port>65535){$(prefix+'-error').textContent='请填写供应商、名称、.invalid 主机和有效端口';return;}
 if(mode==='set'&&(!$(prefix+'-username').value.startsWith('DEMO_')||!$(prefix+'-password').value.startsWith('DEMO_'))){$(prefix+'-error').textContent='原型仅接受 DEMO_ 开头的演示用户名和密码';return;}
 if(allProxies().some(p=>p.id!==existing?.id&&(p.vendorId||1)===vendor&&p.host===host&&p.port===port&&p.protocol===protocol)){$(prefix+'-error').textContent='同一供应商已有该端点';return;}if(!existing&&vendorProxies(v).length>=v.proxyLimit){$(prefix+'-error').textContent='已达到代理数量上限';return;}
 const data={name,host,port,protocol,country:$(prefix+'-country').value,city:$(prefix+'-city').value.trim(),expires:$(prefix+'-expires').value,enabled:$(prefix+'-enabled').checked,notes:$(prefix+'-notes').value.trim(),hasAuth:mode==='keep'?!!existing?.hasAuth:mode==='set'};
 if(!validProxyDate(data.expires)||inline&&(!data.enabled||proxyExpired(data))){$(prefix+'-error').textContent='请选择有效日期；账号内新增的代理需启用且未过期';return;}
 const endpointChanged=!!existing&&(existing.host!==host||existing.port!==port||existing.protocol!==protocol||mode!=='keep');const p=existing||appendProxy(data,vendor);Object.assign(p,data,{version:p.version+1,geoSource:'手动标签'});if(endpointChanged){p.state='未测试';p.latency=null;p.quality=null;p.lastTest='';p.simFailure=host.startsWith('fail.');}
 proxyAudit(p,existing?'修改代理':'新增代理','#'+p.id+' · 保留绑定账号授权/暂停/历史');$(prefix+'-username').value='';$(prefix+'-password').value='';if(inline){accountForm.proxy=p.id;accountForm.inline=false;renderAccountForm();}else{$('modal').close();refreshProxyWorkspace();}notify('代理已保存，账号授权保留；没有发起网络请求。');
}
function showProxyDetail(id){const p=allProxies().find(p=>p.id===id);if(!canReadProxy(p))return;const r=proxyReferences(p);openModal(p.name+' · 代理详情','仅同归属引用 · 密码不回显',detailRows([['归属 / 共享范围',esc(proxyOwner(p).name)+' · 仅本供应商'],['创建者',esc(p.createdBy)],['创建时间',p.created],['地址',esc(p.protocol.toLowerCase()+'://'+p.host+':'+p.port)],['认证',p.hasAuth?'已配置（不回显）':'未配置'],['状态',proxyStatus(p)],['国家 / 地区',regionLabel(p.country)+' · '+esc(p.city||'—')+' · '+esc(p.geoSource||'未检测')],['有效期',p.expires?p.expires+' 23:59 UTC+8':'永不过期'],['最近测试',p.lastTest||'未测试'],['备注',esc(p.notes||'—')]])+'<h3>占用与引用</h3>'+adminTable(['类型','对象','状态'],[...r.bindings.map(a=>['绑定账号',esc(a.name)+' · #'+a.id,badge(status(a))+(a.archived?' <span class="badge archived">已归档</span>':'')]),...r.backup.map(x=>['备用引用',esc(x.name)+' · #'+x.id,'需先解除备用关联']),...(r.sessions?[['OAuth 会话',r.sessions+' 个未完成授权会话','未释放引用']]:[])],'代理引用详情')+'<div class="notice">存在任一引用就不能删除。修改代理只更新出口；不会清除账号授权或静默改为直连。</div>',(canManageProxy(p)?actionButton('edit-proxy','编辑代理',id)+actionButton('px-delete','删除代理',id,'danger'):'<span class="badge info">只读查看</span>')+actionButton('dismiss','关闭',0));}
function proxyDeletePreview(id){const targets=id?proxyTargets(id):proxyScope().filter(p=>proxySelected.has(p.id));if(!targets.length)return;proxyDeleteDraft=targets.map(p=>p.id);const free=targets.filter(p=>!proxyReferences(p).blocked);openModal('删除代理','先检查引用，再删除未占用项',adminTable(['代理','检查结果'],targets.map(p=>{const r=proxyReferences(p);return [esc(p.name)+' · #'+p.id,r.blocked?'不可删除：'+[r.bindings.length?r.bindings.length+' 个绑定账号':'',r.backup.length?r.backup.length+' 个备用引用':'',r.sessions?r.sessions+' 个授权会话':''].filter(Boolean).join('、'):'可删除'];}),'删除预检查')+`<div class="notice">${free.length} 个可删除，${targets.length-free.length} 个保留。删除不会解绑账号、清空账号授权或删除历史用量。</div><label class="checkline"><input id="proxy-delete-confirm" type="checkbox" ${!free.length?'disabled':''}>我确认删除上述未引用代理</label><p id="proxy-delete-error" class="form-error"></p>`,`<button data-action="dismiss">取消</button><button class="danger" data-action="px-delete-confirm" id="proxy-delete-submit" disabled>删除 ${free.length} 个未引用代理</button>`);}
function commitProxyDelete(){if(!$('proxy-delete-confirm')?.checked||!proxyDeleteDraft)return;const results=[];for(const id of proxyDeleteDraft){const p=allProxies().find(x=>x.id===id);if(!canManageProxy(p))continue;if(proxyReferences(p).blocked){results.push([p.name,'保留：仍有引用']);continue;}proxyAudit(p,'删除未引用代理','#'+id+' · 账号和历史未改变');proxies=proxies.filter(x=>x.id!==id);extraProxies=extraProxies.filter(x=>x.id!==id);proxySelected.delete(id);results.push([p.name,'已删除']);}refreshProxyWorkspace();openModal('代理删除结果','逐项结果 · 虚构本地数据',adminTable(['代理','结果'],results),' <button data-action="dismiss">完成</button>');proxyDeleteDraft=null;}
function openProxyChecks(kind,id){
 if(proxyJob?.running)return;
 const targets=proxyTargets(id).filter(canManageProxy);
 if(!targets.length){notify(prototypeText('当前范围没有可检测代理'));return;}
 proxyJob={kind,ids:targets.map(p=>p.id),rows:targets.map(p=>({id:p.id,name:p.name,state:'等待',message:''})),cancelled:false,running:false,role:previewRole,context:proxyContext,single:!!id};
 if(kind==='connect'){runProxyChecks();return;}
 openModal('批量质量检测','手动检测 · 本原型不访问网络',`<div class="notice">${prototypeText('本次检测 {count} 个代理，停用或过期项跳过，不自动启用。',{count:targets.length})}</div><div id="proxy-job-progress"></div>`,'<button data-action="px-check-start" id="proxy-check-start" class="primary">开始演示检测</button><button data-action="px-check-cancel">取消 / 关闭</button>');renderProxyJob();
}
function proxyCheckSummary(job){
 const count=state=>job.rows.filter(r=>r.state===state).length;
 return prototypeText(job.cancelled?'测试已停止：{valid} 个有效，{invalid} 个无效，{skipped} 个跳过，{cancelled} 个未执行':'测试完成：{valid} 个有效，{invalid} 个无效，{skipped} 个跳过',{valid:count('成功'),invalid:count('失败'),skipped:count('跳过'),cancelled:count('取消')});
}
function renderProxyJob(){
 const job=proxyJob,active=!!job?.running,done=job?job.rows.filter(r=>r.state!=='等待'&&r.state!=='检测中').length:0;
 document.querySelectorAll('.proxy-tools [data-action="px-test"]').forEach(b=>{b.disabled=active;b.setAttribute('aria-busy',String(active));if(b.dataset.kind==='connect')b.innerHTML=workbenchIcon(active?'refresh':'checkCircle',active)+'<span>'+prototypeText(active?'测试中':proxySelected.size?'测试已选':'一键测试')+'</span>';});
 const status=$('proxy-test-status');
 if(status){
  const scope=prototypeText(proxySelected.size?'测试范围：已选 {count} 个代理（可跨页）':'测试范围：当前筛选全部 {count} 个代理（含其他页）',{count:proxySelected.size||filteredProxies().length});
  status.innerHTML=active?`<span>${workbenchIcon('refresh',true)}${prototypeText('正在测试 {done} / {count} 个代理',{done,count:job.rows.length})}</span><button class="text-button" data-action="px-check-cancel" ${job.cancelled?'disabled':''}>${prototypeText(job.cancelled?'正在停止…':'停止测试')}</button>`:`<span>${scope}</span>${job&&job.context===proxyContext?`<span class="proxy-test-summary">${prototypeText('上次测试（{count} 个）：',{count:job.rows.length})}${proxyCheckSummary(job)}</span>`:''}`;
 }
 if(job&&$('proxy-job-progress'))$('proxy-job-progress').innerHTML=`<div class="proxy-job-summary">${active?prototypeText('正在测试 {done} / {count} 个代理',{done,count:job.rows.length}):job.started?proxyCheckSummary(job):prototypeText('等待')}</div>`+adminTable(['代理','执行状态','结果'],job.rows.map(r=>[esc(r.name)+' · #'+r.id,prototypeText(r.state),esc(r.message)]),'代理检测结果');
}
async function runProxyChecks(){
 const job=proxyJob;if(!job||job.running)return;
 job.running=true;job.started=true;if($('proxy-check-start'))$('proxy-check-start').disabled=true;renderProxyData();renderProxyJob();
 for(const row of job.rows){
  if(job.cancelled||proxyJob!==job||previewRole!==job.role||proxyContext!==job.context)break;
  const p=allProxies().find(x=>x.id===row.id);
  if(!canManageProxy(p)||!proxyOperational(p)){row.state='跳过';row.message=prototypeText(p?proxyStatus(p):'对象已不存在');renderProxyJob();continue;}
  row.state='检测中';renderProxyData();renderProxyJob();const version=p.version;
  await new Promise(r=>setTimeout(r,350));
  if(job.cancelled||proxyJob!==job||proxyContext!==job.context||previewRole!==job.role)break;
  if(p.version!==version||!canManageProxy(p)||!proxyOperational(p)){row.state='跳过';row.message=prototypeText('配置已变更，请重测');renderProxyJob();continue;}
  const failed=!!p.simFailure;p.state=failed?'异常':'可用';p.latency=failed?null:80+(p.id*71)%700;p.lastTest=DEMO_NOW;
  row.state=failed?'失败':'成功';row.message=prototypeText(failed?'连接超时，账号授权保留':'代理可用，延迟 {latency} ms',{latency:p.latency});
  if(job.kind==='quality'){const partial=p.id===9;p.quality={grade:failed?'D':partial?'C':'A',score:failed?0:partial?67:94,summary:failed?'连接失败':partial?'部分目标受限':'目标可达',latency:p.latency,at:DEMO_NOW};row.message=prototypeText(failed?'连接失败':partial?'部分目标受限':'TLS / Claude / OpenAI 可达');}
  proxyAudit(p,job.kind==='quality'?'手动质量检测':'手动连接测试','#'+p.id+' · '+row.state+'（演示）');renderProxyData();renderProxyJob();
 }
 job.running=false;
 if(proxyJob!==job||proxyContext!==job.context)return;
 job.rows.filter(r=>r.state==='等待'||r.state==='检测中').forEach(r=>{r.state='取消';r.message=prototypeText('未应用检测结果');job.cancelled=true;});
 refreshProxyWorkspace();renderProxyJob();
 if(job.kind==='quality'&&$('proxy-job-progress'))$('modal-actions').innerHTML='<button data-action="dismiss">完成</button>';
 const single=job.rows[0];notify(job.single&&single.state!=='取消'?single.message:proxyCheckSummary(job));
}
async function copyProxyAddress(id){
 const p=allProxies().find(p=>p.id===id);if(!canReadProxy(p))return;
 const address=p.protocol.toLowerCase()+'://'+p.host+':'+p.port;
 try{await navigator.clipboard.writeText(address);const feedback=$('detail-copy-feedback');if(feedback){feedback.hidden=false;feedback.textContent=prototypeText('已复制无认证信息的代理地址');}else notify(prototypeText('已复制无认证信息的代理地址'));}
 catch{openModal('复制脱敏地址','不含用户名和密码','<input aria-label="脱敏代理地址" readonly value="'+esc(address)+'">','<button data-action="dismiss">关闭</button>');}
}

function showProxyReport(id){const p=allProxies().find(p=>p.id===id);if(!canManageProxy(p))return;const q=p.quality;if(!q){openProxyChecks('quality',id);return;}openModal(p.name+' · 质量报告','手动检测快照 · 本地模拟，不代表真实出口质量',detailRows([['评级',q.grade+' / '+q.score],['结果',esc(q.summary)],['采集时间',q.at],['延迟',q.latency==null?'未知':q.latency+' ms'],['地理位置',regionLabel(p.country)+' · '+esc(p.city||'—')],['检测目标','沿用项目固定的 TLS / Claude / OpenAI 检查']])+adminTable(['检查项','结果'],['连接 / TLS','Claude','OpenAI'].map((target,i)=>[target,q.grade==='D'?'连接失败':q.grade==='C'&&i===2?'受限（演示）':'可达（演示）']))+'<div class="notice">检测不清除账号授权、平台禁用或暂停，也不自动替换代理；未检测/未知不等于可用。</div>',actionButton('px-recheck-quality','重新检测',id)+actionButton('dismiss','关闭',0));}
function openProxyExport(){const targets=proxyTargets();if(!targets.length){notify('没有可导出的代理');return;}proxyExportIds=targets.map(p=>p.id);openModal('导出代理清单',targets.length+' 个代理 · '+(proxySelected.size?'已选集合':'当前筛选全部'),'<div class="notice">清单包含名称、协议、脱敏地址、地区、有效期、状态与占用数，不包含用户名、密码或账号授权。演示 JSON 可在本原型回导，只恢复清单资料，认证需重新填写。</div>','<button data-action="px-export-csv">导出 CSV 清单</button><button data-action="px-export-json">导出演示 JSON</button><button data-action="dismiss">取消</button>');}
function exportProxyData(kind){const rows=allProxies().filter(p=>proxyExportIds.includes(p.id)&&canManageProxy(p));if(kind==='csv'){csvDownload('vendor-proxies-demo.csv',['ID','名称','供应商','协议','地址','认证状态','国家地区','城市','占用账号数','状态','延迟ms','有效期','创建时间'],rows.map(p=>[p.id,p.name,proxyOwner(p).name,p.protocol,p.host+':'+p.port,p.hasAuth?'已配置（不导出凭证）':'未配置',regionLabel(p.country),p.city,proxyBindings(p.id).length,proxyStatus(p),p.latency??'',p.expires||'永不过期',p.created]));}else{const payload={type:'sub2api-vendor-proxy-demo',version:1,proxies:rows.map(p=>({name:p.name,protocol:p.protocol,host:p.host,port:p.port,country:p.country,city:p.city,expires:p.expires,notes:p.notes}))};const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.href=url;a.download='vendor-proxies-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}notify('已导出 '+rows.length+' 个代理清单，不含认证秘密。');}
function proxyJsonFields(){proxyImportRows=[];return '<label>选择演示 JSON 文件<input id="proxy-import-file" type="file" accept=".json,application/json"></label><label>或粘贴清单 JSON<textarea id="proxy-import-json" rows="7" spellcheck="false" placeholder="仅接受 sub2api-vendor-proxy-demo v1"></textarea></label><p class="muted small">只新增，不覆盖已有端点。导出清单不含认证，导入后为未测试；需要认证的代理请补充认证。</p><p id="proxy-json-error" class="form-error" role="alert"></p><div id="proxy-json-preview"></div><div class="buttons"><button data-action="px-json-preview">解析预览</button><button id="proxy-json-commit" data-action="px-json-commit" disabled>导入有效条目</button></div>';}
function previewProxyJson(){try{const raw=$('proxy-import-json').value;if(raw.length>100000)throw Error('文件最多100 KB');const data=JSON.parse(raw),vendor=editorOwner('proxy');if(!vendor)throw Error('请选择供应商');if(data.type!=='sub2api-vendor-proxy-demo'||data.version!==1||!Array.isArray(data.proxies)||data.proxies.length>100)throw Error('需要演示清单 v1，最多100条');const seen=new Set();proxyImportRows=data.proxies.map((p,i)=>{if(p&&typeof p.host==='string')p={...p,host:p.host.toLowerCase()};let error='';if(!p||typeof p.name!=='string'||!p.name.trim()||p.name.length>100||!['HTTP','HTTPS','SOCKS5','SOCKS5H'].includes(p.protocol)||typeof p.host!=='string'||!/^([a-z0-9-]+\.)+invalid$/i.test(p.host)||!Number.isInteger(p.port)||p.port<1||p.port>65535)error='名称、协议或演示端点无效';else if(p.country!==undefined&&!PROXY_COUNTRIES.some(x=>x[0]===p.country)||p.city!==undefined&&(typeof p.city!=='string'||p.city.length>100)||p.notes!==undefined&&(typeof p.notes!=='string'||p.notes.length>300)||!validProxyDate(p.expires))error='地区、备注或日期无效';const key=p?.protocol+'|'+p?.host+'|'+p?.port;if(!error&&(seen.has(key)||allProxies().some(x=>(x.vendorId||1)===vendor&&x.protocol===p.protocol&&x.host===p.host&&x.port===p.port)))error='重复：跳过，不覆盖';seen.add(key);return {line:i+1,p,error};});$('proxy-json-error').textContent='';$('proxy-json-preview').innerHTML=adminTable(['行','名称','结果'],proxyImportRows.map(r=>[r.line,esc(r.p?.name||'无效'),r.error||'可新增 · 未测试']));const count=proxyImportRows.filter(r=>!r.error).length;$('proxy-json-commit').disabled=!count;$('proxy-json-commit').textContent='导入 '+count+' 个有效代理';}catch(e){proxyImportRows=[];$('proxy-json-error').textContent=e instanceof SyntaxError?'JSON 格式错误':e.message;$('proxy-json-preview').innerHTML='';$('proxy-json-commit').disabled=true;}}
function commitProxyJson(){previewProxyJson();const rows=proxyImportRows.filter(r=>!r.error),vendor=editorOwner('proxy'),v=vendors.find(v=>v.id===vendor);if(!rows.length)return;if(!v||vendorProxies(v).length+rows.length>v.proxyLimit){$('proxy-json-error').textContent='导入将超过代理上限';return;}for(const r of rows){const x=r.p,p=appendProxy({name:x.name.trim(),protocol:x.protocol,host:x.host.toLowerCase(),port:x.port,country:x.country||'',city:(x.city||'').slice(0,100),expires:x.expires||'',notes:(x.notes||'').slice(0,300),hasAuth:false},vendor);proxyAudit(p,'导入代理清单','#'+p.id+' · 认证需重新配置');r.error='已添加';}refreshProxyWorkspace();$('proxy-json-preview').innerHTML=adminTable(['行','名称','结果'],proxyImportRows.map(r=>[r.line,esc(r.p?.name||'无效'),r.error]));$('proxy-json-commit').disabled=true;$('proxy-json-error').textContent='已新增 '+rows.length+' 个代理，重复或错误行未写入。';$('modal-actions').innerHTML='<button data-action="dismiss">完成</button>';}
document.addEventListener('input',e=>{const t=e.target;if(t.id==='proxy-search'){proxyFilters.q=t.value;proxySelected.clear();proxyPage=1;renderProxyData();}if(t.id==='proxy-import-json'){proxyImportRows=[];$('proxy-json-commit').disabled=true;$('proxy-json-preview').innerHTML='';}});
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.pxFilter){proxyFilters[t.dataset.pxFilter]=t.value;proxyPage=1;proxySelected.clear();renderProxyData();}if(t.dataset.pxSelect){t.checked?proxySelected.add(Number(t.dataset.pxSelect)):proxySelected.delete(Number(t.dataset.pxSelect));updateProxySelection();}if(t.id==='proxy-select-page'){document.querySelectorAll('[data-px-select]').forEach(n=>{n.checked=t.checked;t.checked?proxySelected.add(Number(n.dataset.pxSelect)):proxySelected.delete(Number(n.dataset.pxSelect));});updateProxySelection();}if(t.id==='proxy-page-size'){proxySize=Number(t.value);proxyPage=1;renderProxyData();}if(t.id==='proxy-delete-confirm')$('proxy-delete-submit').disabled=!t.checked;if(t.dataset.pxAuth){for(const key of ['username','password']){$(t.dataset.pxAuth+'-'+key).disabled=t.value!=='set';$(t.dataset.pxAuth+'-'+key).value='';}}if(t.id==='proxy-owner'){proxyEditor.vendor=Number(t.value);if($('proxy-quick'))previewQuick('proxy');if($('proxy-json-commit')){$('proxy-json-commit').disabled=true;proxyImportRows=[];$('proxy-json-preview').innerHTML='';}}if(t.id==='proxy-import-file'){const file=t.files?.[0];if(!file)return;if(file.size>100000){$('proxy-json-error').textContent='文件超过100 KB';return;}const editor=proxyEditor;let raw;try{raw=await file.text();}catch{if(proxyEditor===editor&&$('proxy-json-error'))$('proxy-json-error').textContent='读取失败，请重试或粘贴 JSON';return;}if(proxyEditor!==editor||!$('proxy-import-json'))return;$('proxy-import-json').value=raw;proxyImportRows=[];$('proxy-json-commit').disabled=true;$('proxy-json-preview').innerHTML='';}if(t.id==='preview-role'){proxySelected.clear();proxyContext='';if(proxyJob)proxyJob.cancelled=true;}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const action=b.dataset.action,id=Number(b.dataset.id);if(!action?.startsWith('px-'))return;if(previewRole!=='super_admin'&&previewRole!=='vendor')return;if(previewRole==='vendor'&&ownerPolicy().status!=='active')return;
 if(action==='px-add')openProxyEditor();if(action==='px-import')openProxyEditor(null,'quick');if(action==='px-reset'){proxyFilters=defaultProxyFilters();proxySelected.clear();proxyPage=1;refreshProxyWorkspace();}
 if(action==='px-refresh'){proxyRefresh='已刷新演示快照';refreshProxyWorkspace();notify('列表已刷新；没有触发检测。');}if(action==='px-page'){proxyPage=Number(b.dataset.page);renderProxyData();}if(action==='px-sort'){proxyFilters.direction=proxyFilters.sort===b.dataset.sort&&proxyFilters.direction==='desc'?'asc':'desc';proxyFilters.sort=b.dataset.sort;proxyPage=1;refreshProxyWorkspace();}if(action==='px-clear'){proxySelected.clear();renderProxyData();}
 if(action==='px-dates'){const start=$('proxy-start').value,end=$('proxy-end').value;if(start&&end&&start>end||start>DEMO_TODAY||end>DEMO_TODAY){$('proxy-filter-error').textContent='请选择有效日期，结束不能早于开始或晚于演示今日';return;}proxyFilters.start=start;proxyFilters.end=end;proxySelected.clear();proxyPage=1;$('proxy-filter-error').textContent='';renderProxyData();}
 if(action==='px-copy')await copyProxyAddress(id);
 if(action==='px-delete')proxyDeletePreview(id);if(action==='px-delete-confirm')commitProxyDelete();if(action==='px-test')openProxyChecks(b.dataset.kind,id);if(action==='px-check-start')runProxyChecks();if(action==='px-check-cancel'){if(proxyJob?.running){proxyJob.cancelled=true;b.disabled=true;renderProxyJob();}else{$('modal').close();}}if(action==='px-report')showProxyReport(id);if(action==='px-recheck-quality')openProxyChecks('quality',id);if(action==='px-export')openProxyExport();if(action==='px-export-csv')exportProxyData('csv');if(action==='px-export-json')exportProxyData('json');if(action==='px-json-preview')previewProxyJson();if(action==='px-json-commit')commitProxyJson();
});
$('modal').addEventListener('close',()=>{if($('modal').open)return;if(proxyJob?.kind==='quality'&&proxyJob.running)proxyJob.cancelled=true;proxyImportRows=[];proxyDeleteDraft=null;});
seedProxyMetadata();
seedStatements();
render();
